/*!
 * turn.js 4th release - Simplified version for compatibility
 * Based on turn.js by Emmanuel Garcia
 * Compatible CDN version
 */
(function($) {
    'use strict';

    var cssPrefix = function() {
        var styles = ['transform', 'WebkitTransform', 'MozTransform', 'OTransform', 'msTransform'];
        var el = document.createElement('div');
        for (var i = 0; i < styles.length; i++) {
            if (typeof el.style[styles[i]] !== 'undefined') {
                return styles[i];
            }
        }
        return false;
    }();

    var transformProperty = cssPrefix || 'transform';

    // Main Turn.js function
    $.fn.turn = function(method) {
        var args = Array.prototype.slice.call(arguments, 1);

        return this.each(function() {
            var element = $(this);
            var data = element.data('turn') || {};

            if (typeof method === 'object' || !method) {
                // Initialize
                var options = $.extend({
                    width: 800,
                    height: 600,
                    pages: element.children().length,
                    page: 1,
                    autoCenter: true,
                    acceleration: true,
                    gradients: true,
                    elevation: 50,
                    duration: 800,
                    when: {}
                }, method);

                data.options = options;
                data.pages = options.pages;
                data.page = options.page;
                data.disabled = false;
                data.animating = false;

                element.data('turn', data);
                element.css({
                    width: options.width,
                    height: options.height,
                    position: 'relative'
                });

                // Set up pages
                element.children().each(function(index) {
                    var page = $(this);
                    page.css({
                        position: 'absolute',
                        width: options.width / 2,
                        height: options.height,
                        left: (index % 2 === 0) ? 0 : options.width / 2,
                        top: 0,
                        transformOrigin: (index % 2 === 0) ? 'right center' : 'left center'
                    });
                });

            } else if (typeof method === 'string') {
                // Method calls
                switch (method) {
                    case 'page':
                        if (args.length === 0) {
                            return data.page;
                        } else {
                            var newPage = args[0];
                            if (newPage !== data.page && newPage >= 1 && newPage <= data.pages) {
                                var oldPage = data.page;
                                data.page = newPage;

                                // Trigger events
                                if (data.options.when.turning) {
                                    data.options.when.turning.call(element[0], null, newPage);
                                }

                                // Simple page transition (just show/hide)
                                element.children().each(function(index) {
                                    var pageElement = $(this);
                                    var pageNumber = Math.floor(index / 2) + 1;

                                    if (pageNumber <= newPage) {
                                        pageElement.css('transform', '');
                                    } else {
                                        var transform = (index % 2 === 0) ? 'rotateY(-180deg)' : 'rotateY(180deg)';
                                        pageElement.css('transform', transform);
                                    }
                                });

                                setTimeout(function() {
                                    if (data.options.when.turned) {
                                        data.options.when.turned.call(element[0], null, newPage);
                                    }
                                }, data.options.duration || 800);
                            }
                        }
                        break;

                    case 'pages':
                        return data.pages;

                    case 'next':
                        if (data.page < data.pages) {
                            element.turn('page', data.page + 1);
                        }
                        break;

                    case 'previous':
                        if (data.page > 1) {
                            element.turn('page', data.page - 1);
                        }
                        break;

                    case 'size':
                        if (args.length === 0) {
                            return {
                                width: data.options.width,
                                height: data.options.height
                            };
                        }
                        break;

                    case 'is':
                        return !data.destroyed;

                    case 'destroy':
                        element.removeData('turn');
                        element.children().removeAttr('style');
                        element.removeAttr('style');
                        break;

                    case 'disable':
                        data.disabled = true;
                        break;

                    case 'enable':
                        data.disabled = false;
                        break;

                    case 'disabled':
                        return data.disabled;
                }
            }
        });
    };

    // Simple version - just provide the plugin structure
    $.fn.turn.defaults = {
        width: 800,
        height: 600,
        pages: 1,
        page: 1,
        autoCenter: true,
        acceleration: true,
        gradients: true,
        elevation: 50,
        duration: 800
    };

})(jQuery);